def decode_string(s):
    stack = []
    cur, k = '', 0
    for c in s:
        if c.isdigit():
            k = k * 10 + int(c)
        elif c == '[':
            stack.append((cur, k))
            cur, k = '', 0
        elif c == ']':
            prev, times = stack.pop()
            cur = prev + cur * times
        else:
            cur += c
    return cur
